from lib import *
S = SS('h30')
steps = [
    step("浏览器(本机 Google Chrome,headless)页面和 gRPC 同源(HTTPS、HTTP/2),直接用 fetch 调原生 gRPC(content-type: application/grpc,请求体是 5 字节前缀 + protobuf)。成功的调用:HTTP 200,协议 h2,响应体 14 字节(00000000090a076563686f3a6869,前缀 + echo:hi),响应头 JS 能看到的只有 content-type 和 trailer(只是声明有 trailers),grpc-status 和 grpc-message 读出来都是 null——gRPC 的状态在 HTTP/2 trailers 里,fetch 不让 JS 读 trailers。被服务端拒绝的调用(服务端返回 Unauthenticated):HTTP 200,响应体 0 字节,同样什么状态都读不到。也就是说,JS 能拿到响应数据,但分不清调用是成功还是失败。(注意:这是 grpc.Server 作为 http.Handler 挂在 net/http 上的实测结果。)", t=tl(S(1)), done=lidx(S(1), '被服务端拒绝的调用'), mark=lidx(S(1), '成功的调用'), b=bars([['成功的调用:JS 读到 grpc-status(1=读到)', 0, '读不到'], ['被拒绝的调用:JS 读到 grpc-status', 0, '读不到']], 1.2, mark=[0, 1], done=[]), kv=KV([['数据', 'JS 能读到响应体'], ['trailers', 'fetch 不暴露,grpc-status 读不到'], ['后果', '分不清成功还是失败']], ['后果'])),
    step("跨域(页面在 http://127.0.0.1 的另一个端口)用 fetch 调原生 gRPC:content-type 是 application/grpc,不是“简单请求”,浏览器先发 OPTIONS 预检;gRPC 服务端不会回答 CORS 预检,fetch 抛出 TypeError: Failed to fetch(浏览器实际发出的请求方法记录里有 POST 和 OPTIONS)。所以原生 gRPC 在浏览器里既读不到状态,跨域还连不上。", t=tl(S(2)), done=lidx(S(2), 'fetch 的结果'), mark=lidx(S(2), 'fetch 的结果'), b=bars([['跨域原生 gRPC 的 fetch 是否成功(0=失败)', 0, 'Failed to fetch']], 1.2, done=[0]), kv=KV([['content-type', 'application/grpc,非简单请求'], ['浏览器', '先发 OPTIONS 预检'], ['结果', 'TypeError: Failed to fetch']], ['结果'])),
    step("grpc-web(content-type: application/grpc-web+proto,跨域,经过 improbable-eng/grpc-web v0.15.0 的 Go 包装)的响应体里:成功的调用 HTTP 200,响应体 35 字节共 2 帧——数据帧(标志位 0,长度 9)和 trailers 帧(标志位 128,长度 16,内容 “grpc-status: 0\\r\\n”)。grpc-web 把 trailers 当成响应体最后的一帧发出来,JS 能从 body 里读到。被拒绝的调用:响应体 0 字节,没有帧,grpc-status=16 直接在响应头里(Trailers-Only,16 即 Unauthenticated),并且跨域也能读到(服务端用 CORS 暴露了这个头)。这就是 grpc-web 的核心:把 HTTP/2 trailers 搬进响应体里。", t=tl(S(3)), done=lidx(S(3), '被拒绝的调用'), mark=lidx(S(3), '成功的调用'), b=bars([['成功:响应体字节', 35, '35'], ['其中数据帧字节(长度 9 + 5 前缀)', 14, '14'], ['trailers 帧字节(16 + 5 前缀)', 21, '21']], 38, mark=[2], done=[0, 1]), kv=KV([['数据帧', '标志位 0'], ['trailers 帧', '标志位 128(0x80),内容是 HTTP 头文本'], ['错误(Trailers-Only)', '状态直接在响应头里']], ['trailers 帧'])),
    step("grpc-web 的服务端流:浏览器用 ReadableStream 边收边读,服务端每 200 ms 发一条,三条数据帧到达的时刻是 3 ms、205 ms、407 ms,最后的 trailers 帧(标志位 128,“grpc-status: 0”)在 607 ms。也就是说服务端流在 fetch 上是真正的流式(不是等全部到齐才给)。", t=tl(S(4)), done=lidx(S(4), ' 607 ms'), mark=lidx(S(4), '   3 ms'), b=bars([['第 1 条到达 ms', 3, '3'], ['第 2 条', 205, '205'], ['第 3 条', 407, '407'], ['trailers 帧', 607, '607']], 620, mark=[3], done=[0, 1, 2]), kv=KV([['数据帧', '每 200 ms 一条,到了就能读'], ['trailers 帧', '最后一帧,607 ms'], ['做法', 'fetch + ReadableStream']], ['数据帧'])),
    step("客户端流:把两条消息帧一次性写在同一个请求体里(请求体是缓冲好的),调用 ClientStream,这个 Go 包装下服务端数到 2 条,响应是数据帧 1002(N=2)加 trailers “grpc-status: 0”。也就是说“浏览器不能做客户端流”主要是因为浏览器的 fetch 过去不支持边发边写请求体(见没有验证里的说明),而不是 grpc-web 的帧格式本身不能表达多条消息。需要真正的双向流时,浏览器侧常用 WebSocket(improbable-eng 的包装支持)或者改用别的协议。", t=tl(S(5)), done=lidx(S(5), 'HTTP 200;响应帧'), mark=lidx(S(5), 'HTTP 200;响应帧'), b=bars([['请求体里的消息数', 2, '2'], ['服务端数到的消息数(N)', 2, '2']], 3, done=[0, 1]), kv=KV([['缓冲好的多帧请求体', '服务端按 2 条消息处理'], ['响应', '数据帧 N=2 + trailers 帧'], ['限制的真正原因', '浏览器不能边发边写请求体']], ['限制的真正原因'])),
]
A = mkarth('h30', 30, 'gRPC,gRPC-Web,浏览器,fetch,trailers,CORS,Chrome,真实验证,动画演示',
    '用本机 Chrome 实测:浏览器 fetch 直接调原生 gRPC 能拿到响应体,但读不到 grpc-status(HTTP/2 trailers 不暴露),跨域还因预检失败;grpc-web 把 trailers 变成响应体最后一帧(标志位 128),服务端流可以边收边读。',
    '浏览器为什么不能直接调 gRPC?grpc-web 到底改了什么?这篇用本机的 Chrome 和一个真实的 grpc-web Go 包装,把响应的每一个字节都打印出来。',
    [('读不到 grpc-status', '浏览器 fetch 调原生 gRPC 时,成功和失败的调用 JS 都读不到状态'), ('标志位 128', 'grpc-web 响应体里 trailers 帧的第一个字节(0x80)'), ('3、205、407、607 ms', 'grpc-web 服务端流每一帧到达浏览器的时刻')],
    [('问题在 trailers', '<p>gRPC 把状态放在 HTTP/2 的 trailers 里,而浏览器的 fetch/XHR 不让 JavaScript 读 trailers。调原生 gRPC 能读到数据,读不到成功还是失败。</p>'),
     ('CORS', '<p>content-type 为 application/grpc 的跨域请求会触发预检,gRPC 服务端不会回应预检。需要中间层处理 CORS。</p>'),
     ('grpc-web 的做法', '<p>用 application/grpc-web+proto,响应体里除数据帧外,多一帧标志位为 0x80 的 trailers 帧,内容是 HTTP 头文本(如 grpc-status: 0)。JS 从响应体里就能读到状态。</p>'),
     ('流式', '<p>服务端流可以用 fetch 的 ReadableStream 边收边读。客户端流在浏览器里受限于请求体不能边发边写。</p>'),
     ('要一个代理', '<p>grpc-web 不是原生 gRPC,需要一个能翻译的中间层(Envoy 的 grpc_web 过滤器、improbable-eng 的 Go 包装等)放在 gRPC 服务前面。</p>')],
    steps,
    [ENV_H + '。浏览器是本机的 Google Chrome 154(headless,独立 user-data-dir,--ignore-certificate-errors 只用于这个测试的自签名证书),用 CDP 驱动,代码在 pcdp.py;原生 gRPC 这一节是把 grpc.Server 作为 http.Handler 挂在 net/http 的 HTTPS 服务器上(这样页面和 gRPC 同源),grpc-web 用 improbable-eng/grpc-web v0.15.0(一个较旧但常用的 Go 包装,为此 go.mod 里新增了它的几个依赖);页面服务器、两个 gRPC 服务都在 127.0.0.1',
     '没有验证:grpc.Server 自带的 HTTP/2 传输(而不是 ServeHTTP)在错误时返回 Trailers-Only 的响应头,浏览器能不能从头里读到状态,这里没有测(同源页面的条件没有构造);Envoy 的 grpc_web 过滤器;grpc-web-text(base64)格式;官方 grpc-web JavaScript 客户端库和 connect-web 等;浏览器 fetch 的流式请求体(duplex: half)能不能用于真正的客户端流;WebSocket 传输;Safari、Firefox 的行为'],
    'gRPC-Web')
